ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'localization/stories'
cat=json.loads((BASE/'catalogue.json').read_text(encoding='utf-8'))
parts=runpy.run_path(str(ROOT/'tools/translate-stories.py'))['parts']
